    private Item ingredient(int cell,int craft){return switch(craft){
        case 0->switch(cell){case 1->material("quicksilver_drop");case 3,5->Items.IRON_INGOT;case 4->Items.GLASS;case 7->Items.GOLD_NUGGET;default->Items.AIR;};
        case 1->cell==3 || cell==5?Items.GOLD_INGOT:cell==4?silverwood():Items.AIR;
        case 2->cell==2?tubeItem():cell==6?Items.LEVER:Items.AIR;
        case 3->cell==0?tubeItem():cell==8?Items.LEVER:Items.AIR;
        case 4->cell==8?tubeItem():cell==0?Items.LEVER:Items.AIR;
        case 5->switch(cell){case 0,8->valveItem();case 1,3,5,7->tubeItem();case 2,6->material("vis_filter");default->greatwood();};
        case 6->switch(cell){case 0,2->Items.IRON_INGOT;case 1->Items.DISPENSER;case 3,5->balanced();case 4->constructItem();case 6,8->Items.OAK_PLANKS;default->tubeItem();};
        default->cell<=2?Items.OAK_PLANKS:cell==4 || cell==7?Items.STICK:Items.AIR;
    };}
