    private void verifyPhysicalReturn(ServerPlayer player,UUID id,ItemStack dropped,Item item,String name){require(id!=null && dropped!=null && ItemStack.matches(stack(player,value->value.is(item)),dropped) && player.serverLevel().getEntity(id)==null,"same actual "+name+" UUID physically picked up, never replaced/refunded");report.put("actual_"+name+"_physical_return",Map.of("UUID",id.toString(),"actual_RAW_snbt",snbt(dropped,player),"physical_returns",1,"item_relocations_or_output_grants",0));awaitingMachine=false;}
    private void approachDrop(ServerPlayer player,UUID id,ItemStack dropped,String name){
        if(id==null)return;require(player.serverLevel().getEntity(id) instanceof ItemEntity item && ItemStack.matches(item.getItem(),dropped),"same actual unmoved "+name+" drop until native pickup");ItemEntity item=(ItemEntity)player.serverLevel().getEntity(id);
        // Retain root's accepted diagonal + support + noCollision + actual native
        // contact-envelope approach. ONLY the actor moves; item/UUID/delay do not.
        double[] offsets={0,.8,-.8,1.05,-1.05,1.2,-1.2};for(int rise=0;rise<=3;rise++)for(double x:offsets)for(double z:offsets){Vec3 at=new Vec3(item.getX()+x,bench.getY()+rise,item.getZ()+z);AABB body=player.getBoundingBox().move(at.subtract(player.position()));BlockPos floor=BlockPos.containing(at.x,at.y-.01,at.z);if(!patchBounds().contains(at) || !player.level().noCollision(player,body) || player.level().getBlockState(floor).getCollisionShape(player.level(),floor).isEmpty() || !body.inflate(1,.5,1).intersects(item.getBoundingBox()))continue;report.put("actual_"+name+"_pickup_approach",Map.of("UUID",id.toString(),"unmoved_item_at",item.position().toString(),"collision_checked_player_at",at.toString(),"existing_support",floor.toShortString(),"within_native_contact_envelope",true,"item_relocations_or_output_grants",0));stand(player,at.x,at.y,at.z);return;}throw new IllegalStateException("No collision-free supported native contact approach for "+name+" at "+item.position());
    }
    private BlockPos patchMin(){return bench.offset(-4,-2,-7);}
    private BlockPos patchMax(){return bench.offset(17,8,8);}
    private AABB patchBounds(){return new AABB(Vec3.atLowerCornerOf(patchMin()),Vec3.atLowerCornerOf(patchMax().offset(1,1,1)));}
    private void patch(ServerLevel level){
        for(int x=patchMin().getX()>>4;x<=patchMax().getX()>>4;x++)for(int z=patchMin().getZ()>>4;z<=patchMax().getZ()>>4;z++)level.getChunk(x,z);require(level.getEntitiesOfClass(ItemEntity.class,patchBounds()).isEmpty() && level.getEntitiesOfClass(ExperienceOrb.class,patchBounds()).isEmpty() && level.getEntitiesOfClass(LivingEntity.class,patchBounds()).isEmpty() && pendingView(level).isEmpty(),"new patch refuses all old entities/items/pending/XP");for(BlockPos at:BlockPos.betweenClosed(patchMin(),patchMax()))require(level.getBlockEntity(at)==null && !BuiltInRegistries.BLOCK.getKey(level.getBlockState(at).getBlock()).getNamespace().equals("thaumcraft") && !oldBlocks.containsKey(at),"never overwrite old BE/TC/scanned cells "+at);for(BlockPos at:BlockPos.betweenClosed(patchMin(),patchMax()))level.setBlockAndUpdate(at,at.getY()<bench.getY()?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState());
        // Declared mundane camera platforms: HIGH east strips, LOWER west
        // strips; leave z376..378 a real ground-level source/valve/pickup aisle.
        for(int x=furnacePos.getX()-4;x<=furnacePos.getX()+4;x++)for(int z=furnacePos.getZ()-4;z<=furnacePos.getZ()+4;z++)if(z<=furnacePos.getZ()-2 || z>=furnacePos.getZ()+2)for(int y=bench.getY();y<(x>=furnacePos.getX()?firstPos.getY():secondPos.getY());y++)level.setBlockAndUpdate(new BlockPos(x,y,z),Blocks.STONE.defaultBlockState());
        for(int y=bench.getY();y<leverPos.getY();y++)level.setBlockAndUpdate(new BlockPos(leverPos.getX(),y,leverPos.getZ()),Blocks.STONE.defaultBlockState());
        report.put("declared_mundane_scene",Map.of("min",patchMin().toShortString(),"max",patchMax().toShortString(),"ground_floor_top",bench.getY(),"east_platform_top",firstPos.getY(),"west_platform_top",secondPos.getY(),"aisle_Z",List.of(376,377,378),"lever_pedestal",leverPos.below().toShortString(),"automation_or_resource_fixtures",false));
    }
